+<template>
+  <section class="workouts">
+    <h2>{{ title }}</h2>
+    <p class="clock">{{ now }}</p>
+    <ul>
+      <li v-for="workout in workouts" :key="workout.id">
+        <button type="button" @click="$emit('select', workout.id)">
+          {{ workout.name }}
+        </button>
+      </li>
+    </ul>
+  </section>
+</template>
+
+<script>
+export default {
+  name: "WorkoutList",
+  props: {
+    title: { type: String, required: true },
+    workouts: { type: Array, required: true },
+  },
+  emits: ["select"],
+  data() {
+    return { now: new Date().toLocaleTimeString(), timer: null };
+  },
+  mounted() {
+    this.timer = setInterval(() => {
+      this.now = new Date().toLocaleTimeString();
+    }, 1000);
+  },
+  beforeUnmount() {
+    clearInterval(this.timer);
+  },
+};
+</script>
